package factories

import (
	"context"
	"database/sql"
	"fmt"
	"mortenvistisen/internal/storage"
	"mortenvistisen/models"
	"time"

	"github.com/go-faker/faker/v4"
)

// Factory declarations below are generated by Andurel.

type SubscriberFactory struct {
	models.SubscriberEntity
}

type SubscriberOption func(*SubscriberFactory)

func BuildSubscriber(opts ...SubscriberOption) models.SubscriberEntity {
	f := &SubscriberFactory{
		SubscriberEntity: models.SubscriberEntity{
			Email:        sql.NullString{String: faker.Word(), Valid: true},
			SubscribedAt: sql.NullTime{Time: time.Now(), Valid: true},
			Referer:      sql.NullString{String: faker.Word(), Valid: true},
			IsVerified:   sql.NullBool{Bool: randomBool(), Valid: true},
		},
	}

	for _, opt := range opts {
		opt(f)
	}

	return f.SubscriberEntity
}

func CreateSubscriber(
	ctx context.Context,
	exec storage.Executor,
	opts ...SubscriberOption,
) (models.SubscriberEntity, error) {
	built := BuildSubscriber(opts...)

	entity := models.SubscriberEntity{
		ID:           built.ID,
		CreatedAt:    time.Now(),
		UpdatedAt:    time.Now(),
		Email:        built.Email,
		SubscribedAt: built.SubscribedAt,
		Referer:      built.Referer,
		IsVerified:   built.IsVerified,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.SubscriberEntity{}, err
	}

	return entity, nil
}

func CreateSubscribers(
	ctx context.Context,
	exec storage.Executor,
	count int,
	opts ...SubscriberOption,
) ([]models.SubscriberEntity, error) {
	subscribers := make([]models.SubscriberEntity, 0, count)

	for i := range count {
		entity, err := CreateSubscriber(ctx, exec, opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create subscriber %d: %w", i+1, err)
		}
		subscribers = append(subscribers, entity)
	}

	return subscribers, nil
}

func WithSubscribersEmail(value sql.NullString) SubscriberOption {
	return func(f *SubscriberFactory) {
		f.SubscriberEntity.Email = value
	}
}

func WithSubscribersSubscribedAt(value sql.NullTime) SubscriberOption {
	return func(f *SubscriberFactory) {
		f.SubscriberEntity.SubscribedAt = value
	}
}

func WithSubscribersReferer(value sql.NullString) SubscriberOption {
	return func(f *SubscriberFactory) {
		f.SubscriberEntity.Referer = value
	}
}

func WithSubscribersIsVerified(value sql.NullBool) SubscriberOption {
	return func(f *SubscriberFactory) {
		f.SubscriberEntity.IsVerified = value
	}
}
